
public class PatternThree {

	public static void main(String[] args) {
		// TODO Auto-generated method stub

		for(int i = 3; i >=1; i--){	
			for(int j = 1; j <= i; j++){
				System.out.print('*'); // dont write ln it will print it on new line
		}
		
			System.out.println();
}
		}


}
